package br.com.cuidaplus.api.notification;
import br.com.cuidaplus.api.common.MessageResponse; import br.com.cuidaplus.api.security.AuthenticatedUser; import jakarta.validation.Valid; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController{private final NotificationService service;private final NotificationPreferenceService preferences;public NotificationController(NotificationService s,NotificationPreferenceService p){service=s;preferences=p;}@GetMapping public List<NotificationResponse> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.list(AuthenticatedUser.id(),page,size);}@GetMapping("/unread-count")public Map<String,Long> unread(){return Map.of("count",service.unread(AuthenticatedUser.id()));}@GetMapping("/preferences")public NotificationPreferenceResponse preferences(){return preferences.get(AuthenticatedUser.id());}@PatchMapping("/preferences")public NotificationPreferenceResponse preferences(@Valid @RequestBody UpdateNotificationPreferencesRequest request){return preferences.update(AuthenticatedUser.id(),request);}@PatchMapping("/{id}/read")public NotificationResponse read(@PathVariable UUID id){return service.read(AuthenticatedUser.id(),id);}@PatchMapping("/read-all")public MessageResponse readAll(){service.readAll(AuthenticatedUser.id());return new MessageResponse("Notificações marcadas como lidas.");}@PatchMapping("/{id}/clear")public MessageResponse clear(@PathVariable UUID id){service.clear(AuthenticatedUser.id(),id);return new MessageResponse("Notificação limpa.");}@PatchMapping("/clear-all")public MessageResponse clearAll(){service.clearAll(AuthenticatedUser.id());return new MessageResponse("Notificações limpas com sucesso.");}}
